import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

@RestController
@RequestMapping("/api/data")
public class CsvPreviewController {

 private static final Path DATA_BASE;
 private static final Pattern SAFE_FILENAME = Pattern.compile("^[a-zA-Z0-9_\\-]+\\.csv$");

 static {
 try {
 DATA_BASE = Paths.get("/opt/app/datasets/").toRealPath();
 } catch (IOException e) {
 throw new RuntimeException("Cannot resolve data directory", e);
 }
 }

 @GetMapping("/preview")
 public ResponseEntity<List<String>> previewCsv(@RequestParam String filename) throws IOException {
 if (filename == null || !SAFE_FILENAME.matcher(filename).matches()) {
 return ResponseEntity.badRequest().build();
 }
 Path filePath = DATA_BASE.resolve(filename).normalize();
 if (!filePath.startsWith(DATA_BASE)) {
 return ResponseEntity.status(403).build();
 }
 if (!Files.isRegularFile(filePath)) {
 return ResponseEntity.notFound().build();
 }
 List<String> lines = Files.readAllLines(filePath);
 return ResponseEntity.ok(lines.subList(0, Math.min(10, lines.size())));
 }
}

