from urllib.parse import urlparse
from flask import Flask, request, jsonify

app = Flask(__name__)

BLOCKED_RANGES = [
 ipaddress.ip_network('10.0.0.0/8'),
 ipaddress.ip_network('172.16.0.0/12'),
 ipaddress.ip_network('192.168.0.0/16'),
 ipaddress.ip_network('127.0.0.0/8'),
 ipaddress.ip_network('169.254.0.0/16'),
 ipaddress.ip_network('100.64.0.0/10'),
]

def is_safe_feed_url(url):
 try:
 parsed = urlparse(url)
 if parsed.scheme not in ('http', 'https'):
 return False
 if not parsed.hostname:
 return False
 ip = socket.gethostbyname(parsed.hostname)
 addr = ipaddress.ip_address(ip)
 return not any(addr in net for net in BLOCKED_RANGES)
 except Exception:
 return False

@app.route('/api/feeds/validate', methods=['POST'])
def validate_feed():
 data = request.get_json()
 feed_url = data.get('url', '')
 if not is_safe_feed_url(feed_url):
 return jsonify({'error': 'URL not permitted'}), 400
 resp = requests.get(feed_url, timeout=5, allow_redirects=False,
 headers={'User-Agent': 'FeedValidator/1.0'})
 parsed = feedparser.parse(resp.text)
 if parsed.bozo:
 return jsonify({'valid': False})
 return jsonify({'valid': True, 'title': parsed.feed.get('title'), 'entries': len(parsed.entries)})

