SAFE_FILENAME = re.compile(r'^[a-zA-Z0-9_\-]+\.(docx|doc|odt|txt|xlsx|pptx)$')
ALLOWED_FORMATS = {'pdf', 'docx', 'odt', 'txt', 'xlsx', 'pptx', 'html'}

@app.route('/api/convert/document', methods=['POST'])
def convert_document():
 input_file = request.form.get('input_file', '')
 output_format = request.form.get('output_format', 'pdf')
 if not SAFE_FILENAME.match(input_file):
 return jsonify({'error': 'Invalid filename'}), 400
 if output_format not in ALLOWED_FORMATS:
 return jsonify({'error': 'Unsupported format'}), 400
 result = subprocess.run(
 ['libreoffice', '--headless', '--convert-to', output_format, f'/uploads/{input_file}', '--outdir', '/converted/'],
 capture_output=True, timeout=120
 )
 if result.returncode != 0:
 return jsonify({'error': 'Conversion failed'}), 500
 base = input_file.rsplit('.', 1)[0]
 return jsonify({'result': f'/converted/{base}.{output_format}'})

