 new SecureRandom().nextBytes(salt);
 MessageDigest md = MessageDigest.getInstance("SHA-512");
 md.update(salt);
 byte[] hash = md.digest(rawPassword.getBytes("UTF-8"));
 return new String[]{
 Base64.getEncoder().encodeToString(hash),
 Base64.getEncoder().encodeToString(salt)
 };
 }

 public boolean verify(String rawPassword, String storedHash, String storedSalt) throws Exception {
 byte[] salt = Base64.getDecoder().decode(storedSalt);
 MessageDigest md = MessageDigest.getInstance("SHA-512");
 md.update(salt);
 String computed = Base64.getEncoder().encodeToString(md.digest(rawPassword.getBytes("UTF-8")));
 return computed.equals(storedHash);
 }
}

