import org.apache.kafka.clients.producer.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.util.Properties;

@Service
public class EventPublisher {

 private final KafkaProducer<String, String> producer;

 public EventPublisher(
 @Value("${kafka.bootstrap.servers}") String bootstrapServers,
 @Value("${kafka.sasl.username}") String saslUsername,
 @Value("${kafka.sasl.password}") String saslPassword) {
 if (saslUsername.isBlank() || saslPassword.isBlank()) {
 throw new IllegalStateException("Kafka SASL credentials must be configured");
 }
 Properties props = new Properties();
 props.put("bootstrap.servers", bootstrapServers);
 props.put("security.protocol", "SASL_SSL");
 props.put("sasl.mechanism", "PLAIN");
 props.put("sasl.jaas.config",
 String.format("org.apache.kafka.common.security.plain.PlainLoginModule required username='%s' password='%s';", saslUsername, saslPassword));
 props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
 props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
 this.producer = new KafkaProducer<>(props);
 }
}

